#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int M, N;
    if (!(cin >> M >> N)) return 0;

    vector<vector<int>> estoque(M + 1, vector<int>(N + 1));
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= N; ++j) {
            cin >> estoque[i][j];
        }
    }

    int P;
    cin >> P;

    int vendas = 0;
    for (int k = 0; k < P; ++k) {
        int i, j;
        cin >> i >> j;
        if (estoque[i][j] > 0) {
            estoque[i][j]--;
            vendas++;
        }
    }

    cout << vendas << "\n";

    return 0;
}
